"""Tool catalog for the Python side, read from the file generated by the TypeScript layer.

``src/tools/catalog.ts`` is the single source of truth for tool names, descriptions and input
schemas. ``npm run gen:catalog`` exports it to ``python/generated/tool_catalog.json``; this module
loads that file and derives what the Python code needs from it:

- ``INPUT_SCHEMAS``: JSON Schema per tool, used by ``validation.validate_params``.
- ``TOOL_CATALOG``: the web UI's form description (parameter names, simple types, enum values).
- ``engine_method_for``: which engine method serves a tool.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

CATALOG_PATH = Path(__file__).resolve().parent / "generated" / "tool_catalog.json"

# Parameters that hold a presentation session id; the web UI fills them from the active session.
SESSION_ID_PARAMS = frozenset(
    {"presentation_id", "source_presentation_id", "target_presentation_id", "presentation_id_a", "presentation_id_b"}
)

AGENT_CATEGORY = "Agent"
CHECKER_CATEGORY = "Checkers"
BATCH_TOOL = "pptx_batch"


def _load() -> list[dict[str, Any]]:
    try:
        data = json.loads(CATALOG_PATH.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:  # pragma: no cover - broken checkout
        raise RuntimeError(f"{CATALOG_PATH} is missing. Run `npm run gen:catalog` from the repository root.") from exc
    return data["tools"]


TOOLS: list[dict[str, Any]] = _load()
TOOLS_BY_NAME: dict[str, dict[str, Any]] = {tool["name"]: tool for tool in TOOLS}
INPUT_SCHEMAS: dict[str, dict[str, Any]] = {tool["name"]: tool["input_schema"] for tool in TOOLS}


def engine_method_for(tool: dict[str, Any]) -> str:
    """Name of the method that serves ``tool``.

    Engine tools map ``pptx_<name>`` to ``engine.<name>``; agent and checker tools are routed to
    their own services.
    """
    if tool["category"] == AGENT_CATEGORY:
        return "agent_dispatch"
    if tool["category"] == CHECKER_CATEGORY:
        return "checker_dispatch"
    return tool["name"].removeprefix("pptx_")


def is_engine_tool(tool: dict[str, Any]) -> bool:
    """True for tools an engine method serves directly (not agent, checker or batch tools)."""
    return tool["name"] != BATCH_TOOL and tool["category"] not in (AGENT_CATEGORY, CHECKER_CATEGORY)


# --- Web UI form description -------------------------------------------------------------------


def _ui_type(name: str, schema: dict[str, Any]) -> str:
    variants = schema.get("anyOf")
    if variants:
        kinds = {variant.get("type") for variant in variants}
        if {"number", "string"} <= kinds:
            return "measurement"
        if kinds == {"string"}:
            return "string"
        return "object"

    if "enum" in schema:
        return "enum"

    kind = schema.get("type")
    if kind in ("integer", "number"):
        return "number"
    if kind in ("boolean", "array", "object"):
        return kind
    if schema.get("format") == "uuid":
        return "uuid"
    if name.endswith("_path"):
        return "path"
    return "string"


def _ui_param(name: str, schema: dict[str, Any], required: bool) -> dict[str, Any]:
    param: dict[str, Any] = {
        "name": name,
        "type": _ui_type(name, schema),
        "required": required,
        "description": schema.get("description", ""),
    }
    if param["type"] == "enum":
        param["enum_values"] = list(schema["enum"])
    if name in SESSION_ID_PARAMS:
        param["auto_fill"] = "presentation_id"
    return param


def _ui_tool(tool: dict[str, Any]) -> dict[str, Any]:
    schema = tool["input_schema"]
    required = set(schema.get("required", []))
    return {
        "name": tool["name"],
        "description": tool["description"],
        "category": tool["category"],
        "mutating": tool["mutating"],
        "params": [_ui_param(name, prop, name in required) for name, prop in schema.get("properties", {}).items()],
    }


TOOL_CATALOG: list[dict[str, Any]] = [_ui_tool(tool) for tool in TOOLS]


def get_catalog_by_category() -> dict[str, list[dict[str, Any]]]:
    """Return tools grouped by category, preserving catalog order."""
    groups: dict[str, list[dict[str, Any]]] = {}
    for tool in TOOL_CATALOG:
        groups.setdefault(tool["category"], []).append(tool)
    return groups
